import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import react from '@astrojs/react';
import tailwind from '@astrojs/tailwind';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const baseUrl = process.env.BASE_URL
  ? `${process.env.BASE_URL.replace(/\/$/, '')}/`
  : undefined;

export default defineConfig({
  ...(baseUrl ? { base: baseUrl } : {}),
  server: { port: 14173 },
  integrations: [
    starlight({
      title: 'Ferryx Docs',
      logo: { src: './src/assets/ferryx-icon.png' },
      social: { github: 'https://github.com/ferryx/ferryx' },
      sidebar: [
        {
          label: 'Getting Started',
          items: [{ label: 'Introduction', slug: 'docs/introduction' }],
        },
        {
          label: 'Reference',
          items: [{ label: 'Keyboard Shortcuts', slug: 'docs/shortcuts' }],
        },
      ],
    }),
    react(),
    tailwind({ applyBaseStyles: false }),
  ],
  vite: {
    plugins: [
      {
        name: 'tauri-window-mock',
        resolveId(id) {
          if (id === '@tauri-apps/api/window') return '\0virtual:tauri-window';
        },
        load(id) {
          if (id === '\0virtual:tauri-window') {
            return 'export function getCurrentWindow() { return { startDragging: () => {} }; }';
          }
        },
      },
    ],
    resolve: {
      alias: {
        '@tauri-apps/api/core': path.resolve(__dirname, './src/mock/core.ts'),
        '@tauri-apps/api/event': path.resolve(__dirname, './src/mock/events.ts'),
        '@tauri-apps/plugin-dialog': path.resolve(__dirname, './src/mock/dialog.ts'),
        '@': path.resolve(__dirname, './src'),
        '@ui': path.resolve(__dirname, '../ui/src'),
        'lucide-react': path.resolve(__dirname, './node_modules/lucide-react'),
        '@dnd-kit/core': path.resolve(__dirname, './node_modules/@dnd-kit/core'),
        '@dnd-kit/sortable': path.resolve(__dirname, './node_modules/@dnd-kit/sortable'),
        '@dnd-kit/utilities': path.resolve(__dirname, './node_modules/@dnd-kit/utilities'),
        '@xterm/xterm': path.resolve(__dirname, './node_modules/@xterm/xterm'),
        '@xterm/addon-fit': path.resolve(__dirname, './node_modules/@xterm/addon-fit'),
        '@xterm/addon-webgl': path.resolve(__dirname, './node_modules/@xterm/addon-webgl'),
        '@xterm/addon-search': path.resolve(__dirname, './node_modules/@xterm/addon-search'),
        '@xterm/addon-unicode11': path.resolve(__dirname, './node_modules/@xterm/addon-unicode11'),
        'clsx': path.resolve(__dirname, './node_modules/clsx'),
        'tailwind-merge': path.resolve(__dirname, './node_modules/tailwind-merge'),
        'qrcode': path.resolve(__dirname, './node_modules/qrcode'),
      },
    },
    server: {
      // Native fsevents watcher silently misses edits in this repo; poll instead.
      watch: { usePolling: true, interval: 300 },
    },
  },
});

